def _asset_build_pdf(records, scope_label, photo_loader):
    """Create a private, printable ledger snapshot; report every unavailable image."""
    from io import BytesIO
    from xml.sax.saxutils import escape
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    import base64
    import zlib
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Table, TableStyle, Spacer, PageBreak, Image
    from PIL import Image as PILImage, ImageOps

    font = "AssetNanumGothic"
    if font not in pdfmetrics.getRegisteredFontNames():
        pdfmetrics.registerFont(TTFont(font, BytesIO(zlib.decompress(base64.b64decode(_ASSET_PDF_FONT)))))
    normal = ParagraphStyle("asset", fontName=font, fontSize=9, leading=14, wordWrap="CJK")
    title = ParagraphStyle("asset_title", parent=normal, fontSize=18, leading=26, spaceAfter=12)
    def p(value, style=normal):
        return Paragraph(escape(str(value or "—")).replace("\n", "<br/>"), style)
    def table(rows, widths):
        result = Table([[p(v) for v in row] for row in rows], colWidths=widths, repeatRows=1, hAlign="LEFT")
        result.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#e7eff8")),
            ("GRID", (0, 0), (-1, -1), .4, colors.HexColor("#b7c5d4")),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ("LEFTPADDING", (0, 0), (-1, -1), 6),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 7),
        ]))
        return result
    out = BytesIO()
    doc = SimpleDocTemplate(out, pagesize=A4, rightMargin=32, leftMargin=32, topMargin=36, bottomMargin=36,
                            title="계측기 자산 실사 및 관리대장", author="SMART WORK AI AGENT")
    stamp = _korea_now().strftime("%Y-%m-%d %H:%M")
    completed = sum(r.get("실사상태") == "완료" for r in records)
    story = [p("계측기 자산 실사 및 관리대장", title), p(f"출력 기준: {scope_label} · 생성: {stamp} (한국시간)"),
             p(f"총 {len(records)}대 / 실사 완료 {completed}대 / 미완료 {len(records) - completed}대"), Spacer(1, 12)]
    summary = [["순번 / 완료", "품명 / 모델명", "제조번호", "사용자 / 위치", "실사일 / 상태"]]
    for i, r in enumerate(records, 1):
        summary.append([f"{i} / {'완료' if r.get('실사상태') == '완료' else '미완료'}",
                        f"{r.get('품명', '')}\n{r.get('모델명', '')}", r.get("제조번호", ""),
                        f"{r.get('실사사용자') or r.get('등록사용자', '')}\n{r.get('보관위치', '')}",
                        f"{r.get('실사일', '')}\n{r.get('이상여부', '')}"])
    story.append(table(summary, [57, 139, 110, 112, 113]))
    failures = []
    for i, r in enumerate(records, 1):
        story.extend([PageBreak(), p(f"{i}. {r.get('품명', '')}", title)])
        fields = ["모델명", "제조번호", "등록사용자", "실사사용자", "실사자", "실사일", "보관위치",
                  "보유확인", "이상여부", "이상내용", "비고", "자산상태", "반납일", "실사상태", "실사완료일시"]
        story.append(table([["항목", "내용"]] + [[k, r.get(k, "")] for k in fields], [100, 431]))
        ids = [v.strip() for v in str(r.get("사진파일ID목록") or "").split("|") if v.strip()]
        story.extend([Spacer(1, 12), p(f"실사 사진: {len(ids)}장")])
        for n, file_id in enumerate(ids, 1):
            try:
                data = photo_loader(file_id)
                if not data:
                    raise ValueError("사진 읽기 실패")
                with PILImage.open(BytesIO(data)) as original:
                    photo = ImageOps.exif_transpose(original).convert("RGB")
                    photo.thumbnail((1400, 1400))
                    buf = BytesIO()
                    photo.save(buf, format="JPEG", quality=85)
                    width, height = photo.size
                buf.seek(0)
                scale = min(500 / width, 320 / height)
                from reportlab.platypus import KeepTogether
                story.append(KeepTogether([Spacer(1, 10), p(f"{i}. {r.get('품명', '')} · 사진 {n} / {len(ids)}"), Image(buf, width=width * scale, height=height * scale)]))
            except Exception:
                label = f"{i}번 {r.get('품명', '')} / 사진 {n}"
                failures.append(label)
                story.append(p(f"{label}: 사진을 불러오지 못했습니다. Drive 읽기 권한 또는 원본 파일을 확인하세요."))
    def footer(canvas, document):
        canvas.setFont(font, 8)
        canvas.drawRightString(A4[0] - 32, 20, f"계측기 관리대장 · {document.page}")
    doc.build(story, onFirstPage=footer, onLaterPages=footer)
    return out.getvalue(), failures


def _render_asset_pdf_export(records, filtered):
    with st.expander("📄 현황·사진 포함 관리대장 PDF 출력", expanded=False):
        scope = st.radio("출력 범위", ["전체 관리대장", "현재 조회 결과"], horizontal=True, key="asset_pdf_scope")
        rows = records if scope == "전체 관리대장" else filtered
        label = scope
        if scope == "현재 조회 결과":
            label += " / " + " · ".join(str(st.session_state.get(k, "전체")) for k in
                ["asset_lifecycle_filter", "asset_check_filter", "asset_owner_filter", "asset_location_filter"])
        signature = hashlib.sha256(json.dumps([label, rows], ensure_ascii=False, sort_keys=True, default=str).encode()).hexdigest()
        st.caption(f"저장된 자료 {len(rows)}대를 현황표와 장비별 상세내용·사진으로 출력합니다. 작성 중인 내용은 먼저 저장해 주세요.")
        if st.button("현황·사진 PDF 생성", key="asset_pdf_create", disabled=not rows):
            st.session_state.pop("asset_pdf_result", None)
            try:
                with st.spinner("저장된 사진을 불러와 PDF를 만들고 있습니다…"):
                    data, failures = _asset_build_pdf(rows, label, _worklog_download_drive_image)
                st.session_state["asset_pdf_result"] = (signature, data, failures)
            except ImportError:
                st.error("PDF 출력에는 reportlab 패키지가 필요합니다. 배포 프로젝트 requirements.txt에 reportlab을 추가해 주세요.")
            except Exception as exc:
                st.error(f"PDF 생성 실패: {exc}")
        result = st.session_state.get("asset_pdf_result")
        if result and result[0] == signature:
            if result[2]:
                st.warning(f"사진 {len(result[2])}장을 읽지 못했습니다. PDF에 해당 사진의 누락 표시가 포함되어 있습니다. 권한 확인 후 다시 생성해 주세요.")
            st.download_button("⬇️ 관리대장 PDF 다운로드", result[1], "계측기_자산관리대장.pdf", "application/pdf", key="asset_pdf_download")
            st.caption("다운로드한 PDF를 열고 인쇄하면 현황과 사진을 함께 보관할 수 있습니다.")


def _render_asset_management():
    st.markdown("### 📦 계측기 자산 실사 및 관리대장")
    if not _worklog_current_user():
        st.info("아래 MY WORK LOG에서 개인 인증한 뒤 자산대장을 열어 주세요.")
        return
    st.caption("자산관리 R6 · 표에서 장비 선택 → 사진 저장 · 실사 완료")
    st.caption("제조번호로 실물을 대조한 뒤 보유 여부·사용자·위치·이상 여부·사진을 저장합니다. 사진은 기존 현장기록과 동일한 보안 경로로 관리됩니다.")
    if "asset_records" not in st.session_state:
        _asset_ws, asset_records, asset_message = _asset_load_records()
        if _asset_ws is None:
            st.error(asset_message)
            st.caption("열 구조 진단 — 기존 시트 첫 5행입니다. 제목 행·중복 열이 있다면 이 부분을 확인해 주세요.")
            st.dataframe(pd.DataFrame(st.session_state.get("asset_header_diagnostic", [])), use_container_width=True)
            return
        st.session_state["asset_records"] = asset_records
        st.session_state["asset_message"] = asset_message
    if st.session_state.get("asset_saved_notice"):
        st.info(st.session_state.pop("asset_saved_notice"))
    records = st.session_state["asset_records"]
    if st.session_state.get("asset_header_notice"):
        st.info(st.session_state.pop("asset_header_notice"))
    if st.session_state.get("asset_message"):
        st.warning(st.session_state["asset_message"])

    reload_col, metrics_col = st.columns([0.32, 0.68], vertical_alignment="center")
    with reload_col:
        if st.button("🔄 최신 대장 불러오기", type="primary", use_container_width=True, key="asset_reload"):
            _asset_ws, asset_records, asset_message = _asset_load_records()
            if _asset_ws is not None:
                st.session_state["asset_records"] = asset_records
            st.session_state["asset_message"] = asset_message
            st.rerun()
    with metrics_col:
        confirmed = sum(r.get("실사상태") == "완료" for r in records)
        missing = sum(r.get("보유확인") == "미보유/소재 확인 필요" for r in records)
        defective = sum(r.get("이상여부") in ("이상 있음", "불량") for r in records)
        st.info(f"총 **{len(records)}대** · 실사 완료 **{confirmed}대** · 소재 확인 필요 **{missing}대** · 이상 **{defective}대**")

    with st.container(border=True):
        f1, f2, f3, f4 = st.columns(4)
        with f1:
            lifecycle_filter = st.selectbox("자산구분", ["전체", "현재 보유·임차", "반납완료"], key="asset_lifecycle_filter")
        with f2:
            check_filter = st.selectbox("실사 상태", ["전체", "미실사", "보유 확인", "미보유/소재 확인 필요"], key="asset_check_filter")
        with f3:
            owner_filter = st.selectbox("등록 사용자", ["전체"] + ASSET_USER_OPTIONS, key="asset_owner_filter")
        with f4:
            location_filter = st.selectbox("보관위치", ["전체"] + ASSET_LOCATION_OPTIONS, key="asset_location_filter")
    filtered = [r for r in records if (owner_filter == "전체" or r.get("등록사용자") == owner_filter)
                and (check_filter == "전체" or r.get("보유확인") == check_filter)
                and (location_filter == "전체" or r.get("보관위치") == location_filter)]
    if lifecycle_filter != "전체":
        filtered = [r for r in filtered if (r.get("자산상태") == "반납완료") == (lifecycle_filter == "반납완료")]
    table_cols = ["품명", "모델명", "제조번호", "등록사용자", "실사사용자", "실사일", "보관위치", "보유확인", "이상여부", "사진수", "비고", "자산상태", "반납일", "실사상태", "실사완료일시"]
    st.markdown("**계측기 실사대장**")
    st.caption("표에서 장비 행을 선택하세요. ‘사진 저장 · 실사 완료’ 후 첫 열에 자동 체크됩니다. 다른 행으로 이동하기 전 저장해 주세요.")
    grid = pd.DataFrame(filtered).reindex(columns=table_cols).fillna("")
    grid.insert(0, "완료", [r.get("실사상태") == "완료" for r in filtered])
    grid["실사상태"] = grid["실사상태"].replace("", "미실사")
    # Bind selection positions to the exact filtered ID sequence, never to the full ledger.
    grid_scope = hashlib.sha256(json.dumps([r["자산ID"] for r in filtered]).encode()).hexdigest()[:16]
    import inspect
    if "on_select" in inspect.signature(st.dataframe).parameters:
        event = st.dataframe(
            grid, use_container_width=True, hide_index=True,
            height=380, key=f"asset_grid_{grid_scope}",
            on_select="rerun", selection_mode="single-row",
            column_config={
                "완료": st.column_config.CheckboxColumn("완료", width="small", help="실사 완료 저장에 성공한 장비만 자동 체크됩니다."),
                "품명": st.column_config.TextColumn("품명", width="medium"),
                "모델명": st.column_config.TextColumn("모델명", width="small"),
                "제조번호": st.column_config.TextColumn("제조번호", width="medium"),
            },
        )
        positions = event.selection.rows
        if positions and 0 <= positions[0] < len(filtered):
            clicked_id = filtered[positions[0]]["자산ID"]
            if st.session_state.get("asset_active_id") != clicked_id:
                st.session_state["asset_active_id"] = clicked_id
                st.session_state["asset_form_nonce"] = st.session_state.get("asset_form_nonce", 0) + 1
    else:
        st.dataframe(grid, use_container_width=True, hide_index=True, height=380)
        st.caption("현재 Streamlit 버전은 표 행 선택을 지원하지 않습니다. 아래에서 장비를 선택할 수 있습니다.")
        fallback_ids = [None] + [r["자산ID"] for r in filtered]
        labels = {r["자산ID"]: f"{r.get('품명')} · {r.get('모델명')} · {r.get('제조번호')}" for r in filtered}
        clicked_id = st.selectbox("실사 대상", fallback_ids, format_func=lambda v: labels.get(v, "장비 선택"), key=f"asset_grid_fallback_{grid_scope}")
        if clicked_id and st.session_state.get("asset_active_id") != clicked_id:
            st.session_state["asset_active_id"] = clicked_id
            st.session_state["asset_form_nonce"] = st.session_state.get("asset_form_nonce", 0) + 1

    selected_id = st.session_state.get("asset_active_id")
    selected = next((r for r in filtered if r.get("자산ID") == selected_id), None)
    if selected is not None:
        st.markdown("#### 🔎 현장 실사 등록")
        nonce = st.session_state.get("asset_form_nonce", 0)
        try:
            saved_date = datetime.date.fromisoformat(selected.get("실사일", ""))
        except (ValueError, TypeError):
            saved_date = _korea_now().date()
        with st.form(f"asset_inspection_{selected_id}_{nonce}"):
            st.markdown(f"**{selected.get('품명')}** · 모델 `{selected.get('모델명')}` · 제조번호 `{selected.get('제조번호')}`")
            c1, c2 = st.columns(2)
            with c1:
                ix = ASSET_USER_OPTIONS.index(selected.get("실사사용자")) if selected.get("실사사용자") in ASSET_USER_OPTIONS else 0
                inspector = st.selectbox("실사 사용자", ASSET_USER_OPTIONS, index=ix)
                inspected_date = st.date_input("실사일", value=saved_date, max_value=_korea_now().date())
                st.caption("실사 저장 시 보유 확인으로 기록합니다. 소재 불명 장비는 아래 항목을 선택하세요.")
                not_found = st.checkbox("장비를 찾지 못함", value=selected.get("보유확인") == "미보유/소재 확인 필요")
                possession = "미보유/소재 확인 필요" if not_found else "보유 확인"
            with c2:
                loc_options = ["", "차량", "사무실", "사무실 캐비닛", "현장 보관함", "대여 중", "기타"]
                location = st.selectbox("계측기 위치", loc_options, index=loc_options.index(selected.get("보관위치")) if selected.get("보관위치") in loc_options else 0, format_func=lambda v: "선택해 주세요" if not v else v)
                defect_options = ["미확인", "양호", "불량"]
                default_defect = {"정상": "양호", "이상 있음": "불량", "점검 필요": "미확인"}.get(selected.get("이상여부"), selected.get("이상여부"))
                defect = st.selectbox("장비 상태 (양호 / 불량)", defect_options, index=defect_options.index(default_defect) if default_defect in defect_options else 0)
                defect_detail = st.text_input("이상 내용", value=selected.get("이상내용", ""), placeholder="예: 측정값 불안정, 배터리 교체 필요")
            remark = st.text_area("실사 비고", value=selected.get("비고", ""), placeholder="대여 대상, 차량 번호, 캐비닛 위치 등 추적 가능한 정보를 입력해 주세요.")
